sealed class Outcome3112 {
    data class Success(val payload: String) : Outcome3112()
    data object Failure : Outcome3112()
}

fun describe3112(outcome: Outcome3112): String = when (outcome) {
    is Outcome3112.Success -> outcome.payload
    Outcome3112.Failure -> "failed"
}
